mapper.select:
SELECT wa.* FROM wms_adjust wa LEFT JOIN wms_inbound wi ON wa.inbound_id = wi.id where wa.bool_delete_enum = 0
and wa.review_status = #{reviewStatus}
and wi.basic_class & #{ basicClass} > 0
and wi.serial_number like CONCAT('%', #{serialNumber},'%')
and wi.review_time > #{inboundTime[0]}
and wi.review_time < #{inboundTime[1]}
and wi.supplier_id = #{supplierId}
and wi.project_ids is null
and wi.project_ids IS NOT NULL
and find_in_set(#{projectId},wi.project_ids)
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wa.serial_number like CONCAT('%', #{adjustSerialNumber},'%')
and wa.applicant_name like CONCAT('%', #{operatorName},'%')
and wid.workshop_id in
#{item}
and wi.inbound_way = #{inboundWay}
